import Foundation
import Testing
@testable import AudioFeatures

/// Compares against Hugging Face WhisperFeatureExtractor output
/// generated by Tools/parity/make_mel_fixture.py.
struct LogMelSpectrogramTests {
    private static let tolerance: Float = 1e-4

    @Test func matchesWhisperFeatureExtractor() throws {
        let samples = try Self.loadFloats("input-samples")
        let expected = try Self.loadFloats("whisper-base-mel")

        let features = LogMelSpectrogram(melBandCount: 80).features(for: samples)

        #expect(features.melBandCount == 80)
        #expect(features.frameCount == 3_000)
        let largestError = zip(features.values, expected).map { abs($0 - $1) }.max() ?? .infinity
        #expect(largestError < Self.tolerance, "largest error \(largestError)")
    }

    @Test(arguments: [80, 128])
    func matchesFasterWhisperFeatureExtractor(melBandCount: Int) throws {
        let samples = try Self.loadFloats("input-samples")
        let expected = try Self.loadFloats("faster-whisper-mel-\(melBandCount)")

        let features = LogMelSpectrogram(melBandCount: melBandCount, framing: .wholeSignal).features(for: samples)

        #expect(features.melBandCount == melBandCount)
        #expect(features.frameCount == samples.count / LogMelSpectrogram.hopLength + 1)
        #expect(features.values.count == expected.count)
        let largestError = zip(features.values, expected).map { abs($0 - $1) }.max() ?? .infinity
        #expect(largestError < Self.tolerance, "largest error \(largestError)")
    }

    @Test func trimsInputLongerThanThirtySeconds() {
        let spectrogram = LogMelSpectrogram()
        let window = [Float](repeating: 0.1, count: LogMelSpectrogram.windowSampleCount)
        let longer = window + [Float](repeating: 0.9, count: 16_000)
        #expect(spectrogram.features(for: longer) == spectrogram.features(for: window))
    }

    @Test func slaneyMelScaleRoundTrips() {
        for hertz in [0.0, 440.0, 1_000.0, 4_000.0, 8_000.0] {
            let roundTrip = SlaneyMelScale.hertz(fromMel: SlaneyMelScale.mel(fromHertz: hertz))
            #expect(abs(roundTrip - hertz) < 1e-9)
        }
    }

    private static func loadFloats(_ name: String) throws -> [Float] {
        let url = try #require(Bundle.module.url(forResource: name, withExtension: "f32", subdirectory: "Fixtures"))
        let data = try Data(contentsOf: url)
        return data.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
    }
}
